  ffi.Pointer<ffi.Char> ob_version() {
    return _ob_version();
  }

  late final _ob_versionPtr =
      _lookup<ffi.NativeFunction<ffi.Pointer<ffi.Char> Function()>>(
        'ob_version',
      );
  late final _ob_version = _ob_versionPtr
      .asFunction<ffi.Pointer<ffi.Char> Function()>();
}

