final class ob_audio_command extends ffi.Struct {
  @ffi.UnsignedInt()
  external int typeAsInt;

  ob_audio_type get type => ob_audio_type.fromValue(typeAsInt);
  set type(ob_audio_type value) => typeAsInt = value.value;

  /// playing instance id; stop/fade refer to it
  external ffi.Pointer<ffi.Char> id;

  /// play
  external ffi.Pointer<ffi.Char> sound;

  external ffi.Pointer<ffi.Char> asset;

  /// NULL = master
  external ffi.Pointer<ffi.Char> bus;

  @ffi.Double()
  external double volume;

  @ffi.Double()
  external double rate;

  @ffi.Double()
  external double fade_in;

  @ffi.Int()
  external int loop;

  external ffi.Pointer<ffi.Char> source;

  /// stop: fade-out seconds; fade: target volume (volume) over duration
  @ffi.Double()
  external double fade;

  @ffi.Double()
  external double duration;

  /// mix: 1 = `bus` (NULL = master) muted, 0 = unmuted. Appended last so older callers keep their layout.
  @ffi.Int()
  external int muted;

  static ffi.Pointer<ob_audio_command> $allocate(
    ffi.Allocator $allocator, {
    required ob_audio_type type,
    required ffi.Pointer<ffi.Char> id,
    required ffi.Pointer<ffi.Char> sound,
    required ffi.Pointer<ffi.Char> asset,
    required ffi.Pointer<ffi.Char> bus,
    required double volume,
    required double rate,
    required double fade_in,
    required int loop,
    required ffi.Pointer<ffi.Char> source,
    required double fade,
    required double duration,
    int muted = 0,
  }) => $allocator<ob_audio_command>()
    ..ref.type = type
    ..ref.id = id
    ..ref.sound = sound
    ..ref.asset = asset
    ..ref.bus = bus
    ..ref.volume = volume
    ..ref.rate = rate
    ..ref.fade_in = fade_in
    ..ref.loop = loop
    ..ref.source = source
    ..ref.fade = fade
    ..ref.duration = duration
    ..ref.muted = muted;
}

typedef ob_audio_fn = ffi.Pointer<ffi.NativeFunction<ob_audio_fnFunction>>;
typedef ob_audio_fnFunction =
    ffi.Void Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<ob_audio_command> command,
    );
typedef Dartob_audio_fnFunction =
    void Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<ob_audio_command> command,
    );

/// OB_AUDIO_MIX: a setMute listener action muted (muted = 1) or unmuted `bus` (NULL = the master) on top of the
/// document's mix; apply it to that bus's gain (or every sound for the master).
enum ob_audio_type {
  OB_AUDIO_PLAY(0),
  OB_AUDIO_STOP(1),
  OB_AUDIO_FADE(2),
  OB_AUDIO_MIX(3);

  final int value;
  const ob_audio_type(this.value);

  static ob_audio_type fromValue(int value) => switch (value) {
    0 => OB_AUDIO_PLAY,
    1 => OB_AUDIO_STOP,
    2 => OB_AUDIO_FADE,
    3 => OB_AUDIO_MIX,
    _ => throw ArgumentError('Unknown value for ob_audio_type: $value'),
  };
}

enum ob_blend {
  OB_BLEND_NORMAL(0),
  OB_BLEND_ADDITIVE(1),
  OB_BLEND_MULTIPLY(2),
  OB_BLEND_SCREEN(3);

  final int value;
