  static ob_blend fromValue(int value) => switch (value) {
    0 => OB_BLEND_NORMAL,
    1 => OB_BLEND_ADDITIVE,
    2 => OB_BLEND_MULTIPLY,
    3 => OB_BLEND_SCREEN,
    _ => throw ArgumentError('Unknown value for ob_blend: $value'),
  };
}

