/// One draw call worth of geometry, in draw order. Pointers stay valid until the instance changes.
final class ob_draw_item extends ffi.Struct {
  external ffi.Pointer<ffi.Char> slot;

  external ffi.Pointer<ffi.Char> attachment;

  @ffi.UnsignedInt()
  external int kindAsInt;

  ob_item_kind get kind => ob_item_kind.fromValue(kindAsInt);
  set kind(ob_item_kind value) => kindAsInt = value.value;

  @ffi.UnsignedInt()
  external int blendAsInt;

  ob_blend get blend => ob_blend.fromValue(blendAsInt);
  set blend(ob_blend value) => blendAsInt = value.value;

  /// Texture id (image or atlas page id, or "@openbone/particle-dot"), NULL = untextured (solid colour).
  external ffi.Pointer<ffi.Char> texture_id;

  /// NULL for the particle dot
  external ffi.Pointer<ffi.Char> texture_src;

  @ffi.Double()
  external double texture_width;

  @ffi.Double()
  external double texture_height;

  /// x,y pairs, skeleton space
  external ffi.Pointer<ffi.Float> vertices;

  /// u,v pairs, 0..1 in the texture, v down
  external ffi.Pointer<ffi.Float> uvs;

  @ffi.Int()
  external int vertex_count;

  external ffi.Pointer<ffi.Uint16> indices;

  @ffi.Int()
  external int index_count;

  /// Tint (straight alpha). Ignored when `colors` is set.
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> color;

  /// Two-colour tint: output = dark + (color - dark) * texture.rgb; has_dark = 0 means black (plain multiply).
  @ffi.Int()
  external int has_dark;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> dark;

  /// Per-vertex RGBA (particles), or NULL.
  external ffi.Pointer<ffi.Float> colors;

  /// Index of the clipping mask (ob_instance_clip) this item is drawn inside, or -1.
  @ffi.Int()
  external int clip;

  /// Text attachments: resolved content and style; the box (width × height) is centred on text_matrix's origin.
  external ffi.Pointer<ffi.Char> text;

  external ffi.Pointer<ffi.Char> font;

  @ffi.Double()
  external double font_size;

  @ffi.Double()
  external double font_weight;

  /// 0 left, 1 center, 2 right
  @ffi.Int()
  external int text_align;

  @ffi.Double()
  external double text_width;

  @ffi.Double()
  external double text_height;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> text_fill;

  @ffi.Int()
  external int has_outline;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> text_outline;

  @ffi.Double()
  external double outline_width;

  /// a, b, c, d, x, y (box centre to skeleton space)
  @ffi.Array.multi([6])
  external ffi.Array<ffi.Double> text_matrix;

  /// Shapes: stroke (has_stroke, colour, width); vertices are the outline.
  @ffi.Int()
  external int has_stroke;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> stroke_color;

  @ffi.Double()
  external double stroke_width;
}

